units=[]
for i,row in enumerate(rows.splitlines()):
 level,title,rule,sentence,gap,answer,wrong,text,question,right,no,writing=row.split('|')
 # Alternating answer positions prevent a constant correct-button pattern.
 def choices(q,a,b,ex):
  opts=[a,b] if i%2==0 else [b,a]
  return dict(prompt=q,options=opts,answer=opts.index(a),explanation=ex)
 units.append(dict(id=f'companion-{i+1:02}',level=level,title=title,rule=rule,example=sentence,reading=text,writing=writing,speaking=f'Erzähle frei zum Thema „{title}“. Sprich etwa eine Minute. Höre dir deine Aufnahme an und prüfe Verständlichkeit und Satzstellung.',questions=[choices(gap,answer,wrong,rule),choices(question,right,no,text)],gap=dict(prompt='Schreibe den vollständigen Beispielsatz aus dem Gedächtnis.',answers=[sentence],explanation=rule)))
Path('js/companion-data.js').write_text('/* Original exercises. No publisher content; no verified textbook chapter mapping. */\nwindow.COMPANION_UNITS = '+json.dumps(units,ensure_ascii=False,indent=2)+';\n')
